{"path": "fizzbuzz.py", "content": "def fizzbuzz(n):
    """Return the FizzBuzz sequence for 1..n as a list of strings."""
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result


if __name__ == "__main__":
    import sys

    for line in fizzbuzz(int(sys.argv[1]) if len(sys.argv) > 1 else 100):
        print(line)
