{"path": "test_fizzbuzz.py", "content": "import unittest

from fizzbuzz import fizzbuzz


class FizzBuzzTest(unittest.TestCase):
    def test_zero_returns_empty_list(self):
        self.assertEqual(fizzbuzz(0), [])

    def test_negative_returns_empty_list(self):
        self.assertEqual(fizzbuzz(-5), [])

    def test_one(self):
        self.assertEqual(fizzbuzz(1), ["1"])

    def test_first_fifteen(self):
        self.assertEqual(
            fizzbuzz(15),
            ["1", "2", "Fizz", "4", "Buzz", "Fizz", "7", "8", "Fizz", "Buzz",
             "11", "Fizz", "13", "14", "FizzBuzz"],
        )

    def test_length_matches_n(self):
        self.assertEqual(len(fizzbuzz(100)), 100)

    def test_multiples(self):
        result = fizzbuzz(100)
        for i, value in enumerate(result, start=1):
            if i % 15 == 0:
                self.assertEqual(value, "FizzBuzz")
            elif i % 3 == 0:
                self.assertEqual(value, "Fizz")
            elif i % 5 == 0:
                self.assertEqual(value, "Buzz")
            else:
                self.assertEqual(value, str(i))

    def test_all_values_are_strings(self):
        self.assertTrue(all(isinstance(v, str) for v in fizzbuzz(30)))


if __name__ == "__main__":
    unittest.main()
"}
